(function () {
  'use strict';

  var SWATCH_COUNT = 5;
  var swatchesEl = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');

  var colors = [];
  var locks = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var a = s * Math.min(l, 1 - l);
    function f(n) {
      var k = (n + h / 30) % 12;
      var c = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * c).toString(16).padStart(2, '0');
    }
    return '#' + f(0) + f(8) + f(4);
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generatePalette() {
    var baseHue = randomInt(0, 359);
    var scheme = randomInt(0, 2);
    var offsets;

    if (scheme === 0) {
      offsets = [0, 30, 60, 180, 210];
    } else if (scheme === 1) {
      offsets = [0, 120, 240, 60, 300];
    } else {
      offsets = [0, 45, 90, 135, 180];
    }

    var sat = randomInt(55, 85);
    var lightBase = randomInt(35, 65);

    var next = [];
    for (var i = 0; i < SWATCH_COUNT; i++) {
      if (locks[i] && colors[i]) {
        next.push(colors[i]);
        continue;
      }
      var h = (baseHue + offsets[i]) % 360;
      var l = Math.min(80, Math.max(25, lightBase + (i % 2 === 0 ? 0 : 8)));
      next.push(hslToHex(h, sat, l));
    }
    colors = next;
    render();
  }

  function toggleLock(index) {
    locks[index] = !locks[index];
    render();
  }

  function render() {
    swatchesEl.innerHTML = '';
    colors.forEach(function (hex, i) {
      var swatch = document.createElement('div');
      swatch.className = 'swatch';
      swatch.setAttribute('role', 'listitem');

      var colorDiv = document.createElement('div');
      colorDiv.className = 'swatch-color';
      colorDiv.style.background = hex;

      var info = document.createElement('div');
      info.className = 'swatch-info';

      var hexLabel = document.createElement('span');
      hexLabel.className = 'hex';
      hexLabel.textContent = hex.toUpperCase();

      var lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', locks[i] ? 'true' : 'false');
      lockBtn.setAttribute('aria-label', (locks[i] ? 'Unlock' : 'Lock') + ' color ' + hex.toUpperCase());
      lockBtn.textContent = locks[i] ? '\uD83D\uDD12 Locked' : '\uD83D\uDD13 Lock';
      lockBtn.addEventListener('click', (function (idx) {
        return function () { toggleLock(idx); };
      })(i));

      info.appendChild(hexLabel);
      info.appendChild(lockBtn);
      swatch.appendChild(colorDiv);
      swatch.appendChild(info);
      swatchesEl.appendChild(swatch);
    });
  }

  generateBtn.addEventListener('click', generatePalette);

  for (var i = 0; i < SWATCH_COUNT; i++) {
    locks[i] = false;
  }

  generatePalette();
})();
